import sys, io
md, hist = sys.argv[1], sys.argv[2]   # CLAUDE.md, CLAUDE-history.md
s = io.open(md, encoding='utf-8').read()
def R(old, new):
    global s
    assert s.count(old) == 1, old[:80]
    s = s.replace(old, new)
R("Pushed up to EC (`754294a`) on 2026-10-31. ED and EE committed, waiting for her push.", "Pushed up to EC (`754294a`) on 2026-10-31. ED, EE and EF committed, waiting for her push.")
R("- Push: ED and EE (two commits), before she opens a cloud window.", "- Push: ED, EE and EF (three commits), before she opens a cloud window.")
R("The dashboard's house has 67 rooms (td796). |", "The dashboard's house has 67 rooms (td796). The Beginner Workbooks, fun first (EF, her 31 Oct 23:05 and 23:22): only the parts better changed, each swapped for a game that practises the same thing (none added): the hidden note (ch. 7), the finger code and the same tune, higher (ch. 5, in place of two free tasks), the voice ladder (ch. 8), the secret word (ch. 10), spot the wrong bar (ch. 12), the step trail (ch. 13); the word, picture or flag checks the answers (sc/wbf44.code.js). |")
i = s.index("1. The Workbooks, fun first, floor by floor."); j = s.index("\n", i)
s = s[:i] + "1. The Workbooks, fun first, floor by floor: the Beginner floor done (EF); next the Prelim floor, the same way (her plan first, then one page, then the rest; only the parts better changed). Her 31 Oct 19:49: no cloud session today; for a cloud window later, the prompts are in _workspace/concept-book-kit/HANDOFF-cloud.md (each window pushes its own branch, never main, for her to merge). Then a Pieces shelf (her 22:31) once she says which grade and what for." + s[j:]
io.open(md, 'w', encoding='utf-8').write(s)
h = io.open(hist, encoding='utf-8').read().split('\n')
idx = [i for i, l in enumerate(h) if l.startswith('| 775 |')]
assert len(idx) == 1 and not any(l.startswith('| 776 |') for l in h)
h[idx[0] + 1:idx[0] + 1] = [
 "| 776 | 2026-10-31 | **The Beginner Workbooks, fun first (Build EF; her 23:05 'show me the plan first', 23:22 'yes' to the plan and to the first page, 23:31 'make them').** All 12 Beginner Workbooks read page by page (Ear Prep has none). Six left as they are, already playful, set and done alone: Posture, Keyboard Patterns, Pulse, the Musical Alphabet, the Staff, Line and Space Names. In the other six, seven parts swapped for a game that practises the same thing, none added, so pages and parts stay as they were; three check themselves (a word, a picture, a flag). Ch. 7 p. 4 YOUR TURN 'Draw the sound lines' (the same task as p. 3) → the hidden note: colour every 3-beat note in a grid of 66 and a big dotted minim appears; circle its name, write its beats (NV_HIDE; minims the most common other note, the one to mix up). Ch. 5 p. 6 PLAY 'Make your own echo' (free, and needed someone at home: Book rules 3 and 4) → the finger code: finger numbers in each hand and position spell EGG, BAG, FED, DAD (HP_CODE); p. 7 PLAY 'Write your own tune' (free) → the same tune, higher: the room's Hot cross buns and Mary had a little lamb (MT_SONGS) in C position and G position letters; p. 5 PLAY 'Draw the mirror' (two hands traced in a box 3 cm tall, and the page 6 px over) → fill in the mirror (5 4 3 2 1 | 1 2 3 4 5, the twin 3s coloured); pp. 3 and 4 the letter ladder drawn as a ladder and the bridge drawn bigger, to fill. Ch. 8 p. 3 YOUR TURN (number the signs again, circle the louder) → the voice ladder: classroom talk, a whisper, playground shout, library voice, each set as loud as it is, write mf pp f p (the voices of the old dynamics opener, VolumeLadder; the turtle-and-bird sound pictures kept out, since they teach high and low). Ch. 10 p. 3 PLAY (draw one second note, four times) → the secret word: from a red note follow skip up, same / step down, step down, draw each note, the letters spell EGG and FED (SSK_WORDS). Ch. 12 p. 3 YOUR TURN (four more time signatures) → spot the wrong bar: a 3/4 tune and a 4/4 tune, each with one bar a beat too long (TS_WRONG). Ch. 13 p. 3 PLAY (half or whole, four more pairs) → the step trail: from the star on C, whole up, half up, whole up, whole up, half up, whole up, half down, numbers written on D E♭ F G A♭ B♭ A, the last on the flag (TN_TRAIL). Teacher copies: every new answer computed from the same data; PLAY renumbered where a part's count changed. Workbooks stay English, as every Workbook. Code sc/wbf44.code.js, source sc/patch808.py; test sc/ef809.js (the parts, nothing over in the six Workbooks and Teacher copies, the words, picture, bars and trail); the full set. |",
]
io.open(hist, 'w', encoding='utf-8').write('\n'.join(h))
print('CLAUDE.md and CLAUDE-history.md updated (row 776)')
